stageCss:
#stage .qs-scene{ position:relative; width:100%; height:100%; display:flex; flex-direction:column; gap:14px; }

/* ============================== TOP STRIP ============================== */
#stage .qs-top{
  height:78px; flex-shrink:0; display:flex; align-items:center; gap:14px;
  padding:0 22px; border-radius:20px; white-space:nowrap;
  background:rgba(20,27,43,.78); border:1.5px solid var(--border);
}
#stage .qs-mark{
  width:46px; height:46px; border-radius:13px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.14); border:1.5px solid rgba(58,160,255,.42); color:var(--accent-1);
}
#stage .qs-mark svg{ width:25px; height:25px; }
#stage .qs-app{
  color:var(--text-primary); font-family:var(--font-mono); font-size:21px; font-weight:600;
  overflow:hidden; text-overflow:ellipsis; min-width:0;
}
#stage .qs-rt{ margin-left:auto; flex-shrink:0; display:flex; align-items:baseline; gap:8px; }
#stage .qs-rt b{
  color:#fff; font-family:var(--font-mono); font-size:28px; font-weight:700;
  font-variant-numeric:tabular-nums; transition:color .3s ease;
}
#stage .qs-rt.bad b{ color:var(--danger); }
#stage .qs-rt.ok b{ color:var(--success); }
#stage .qs-rt i{ color:var(--text-dim); font-size:18px; font-weight:600; font-style:normal; }
#stage .qs-health{
  flex-shrink:0; display:flex; align-items:center; gap:8px; padding:7px 14px; border-radius:100px;
  border:1.5px solid rgba(63,185,80,.45); background:rgba(63,185,80,.1);
  transition:border-color .3s ease, background .3s ease;
}
#stage .qs-health i{
  width:10px; height:10px; border-radius:50%; background:var(--success);
  box-shadow:0 0 12px var(--success); animation:msd-breathe 2s ease-in-out infinite;
}
#stage .qs-health b{ color:var(--success); font-family:var(--font-mono); font-size:18px; font-weight:700; }
#stage .qs-health.warn{ border-color:rgba(240,166,74,.55); background:rgba(240,166,74,.12); }
#stage .qs-health.warn i{ background:var(--warn); box-shadow:0 0 12px var(--warn); animation-duration:.6s; }
#stage .qs-health.warn b{ color:var(--warn); }
#stage .qs-health.bad{ border-color:rgba(244,74,106,.55); background:rgba(244,74,106,.12); }
#stage .qs-health.bad i{ background:var(--danger); box-shadow:0 0 12px var(--danger); animation-duration:.45s; }
#stage .qs-health.bad b{ color:var(--danger); }

/* ============================= SCENE STACK ============================= */
#stage .qs-body{ position:relative; flex:1; min-height:0; }
#stage .qs-sc{
  position:absolute; inset:0; opacity:0; transform:scale(.986); pointer-events:none;
  transition:opacity .3s ease, transform .3s cubic-bezier(.22,1,.36,1);
}
#stage .qs-sc.on{ opacity:1; transform:none; }
#stage .qs-sc.whip{ animation:qs-whip .44s cubic-bezier(.19,1,.22,1); }

/* ======================= SCENE 1 · THE FROZEN APP ====================== */
#stage .qs-frozen, #stage .qs-q{ display:flex; flex-direction:column; gap:14px; height:100%; }

#stage .qs-client{
  height:124px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:24px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2));
  border:1.5px solid var(--border);
  transition:border-color .3s ease, box-shadow .3s ease;
}
#stage .qs-client.tight{ height:112px; }
#stage .qs-client.bad{ border-color:rgba(244,74,106,.6); box-shadow:0 0 0 1px rgba(244,74,106,.22), 0 0 46px rgba(244,74,106,.16); }
#stage .qs-client.ok{ border-color:rgba(63,185,80,.55); box-shadow:0 0 0 1px rgba(63,185,80,.22), 0 0 46px rgba(63,185,80,.14); }
#stage .qs-client-ic{
  width:58px; height:58px; border-radius:16px; flex-shrink:0; font-size:29px;
  display:flex; align-items:center; justify-content:center;
  background:linear-gradient(160deg,#26344e,#1a2338); border:1.5px solid var(--border);
}
#stage .qs-client-t{ display:flex; flex-direction:column; gap:6px; min-width:0; }
#stage .qs-client-t b{ color:#fff; font-size:27px; font-weight:800; letter-spacing:-.3px; white-space:nowrap; }
#stage .qs-client-t i{ color:var(--text-dim); font-family:var(--font-mono); font-size:18px; font-weight:600; font-style:normal; white-space:nowrap; }
#stage .qs-client-b{
  margin-left:auto; flex-shrink:0; padding:9px 18px; border-radius:100px; white-space:nowrap;
  border:1.5px solid rgba(240,166,74,.5); background:rgba(240,166,74,.12); color:var(--warn);
  font-family:var(--font-mono); font-size:19px; font-weight:700; letter-spacing:1.2px;
  transition:border-color .3s ease, background .3s ease, color .3s ease;
}
#stage .qs-client-b.ok{ border-color:rgba(63,185,80,.5); background:rgba(63,185,80,.14); color:var(--success); letter-spacing:0; }
#stage .qs-client-b.bad{ border-color:rgba(244,74,106,.6); background:rgba(244,74,106,.16); color:var(--danger); }

#stage .qs-wait{
  flex:1; min-height:0; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:14px;
  border-radius:26px;
  background:radial-gradient(circle at 50% 40%, rgba(240,166,74,.1), transparent 62%), rgba(20,27,43,.5);
  border:2px dashed rgba(240,166,74,.35);
  transition:border-color .3s ease, background .3s ease;
}
#stage .qs-wait.bad{
  border-color:rgba(244,74,106,.55); border-style:solid;
  background:radial-gradient(circle at 50% 40%, rgba(244,74,106,.14), transparent 62%), rgba(20,27,43,.5);
}
#stage .qs-spin{
  width:58px; height:58px; border-radius:50%; flex-shrink:0;
  border:5px solid rgba(240,166,74,.2); border-top-color:var(--warn);
  animation:msd-spin 1s linear infinite;
}
#stage .qs-wait.bad .qs-spin{ border-color:rgba(244,74,106,.2); border-top-color:var(--danger); }
#stage .qs-wait-n{
  color:#fff; font-family:var(--font-mono); font-size:74px; font-weight:800;
  line-height:1; letter-spacing:-2px; font-variant-numeric:tabular-nums;
}
#stage .qs-wait-t{ color:var(--text-dim); font-size:24px; font-weight:600; }

#stage .qs-steps{ height:110px; flex-shrink:0; display:flex; align-items:center; gap:10px; }
#stage .qs-step{
  flex:1; min-width:0; display:flex; flex-direction:column; align-items:center; gap:6px;
  padding:14px 6px; border-radius:16px; white-space:nowrap;
  background:rgba(14,20,32,.7); border:1.5px solid var(--border); color:var(--text-dim);
  font-family:var(--font-mono); font-size:17px; font-weight:600;
  transition:border-color .3s ease, color .3s ease, background .3s ease;
}
#stage .qs-step i{ color:var(--text-dim); font-size:16px; font-weight:700; font-style:normal; }
#stage .qs-step.on{
  border-color:rgba(240,166,74,.6); background:rgba(240,166,74,.1); color:var(--warn);
}
#stage .qs-step.on i{ color:#fff; }

#stage .qs-api{
  height:130px; flex-shrink:0; display:flex; flex-direction:column; gap:14px; justify-content:center;
  padding:16px 22px; border-radius:24px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2));
  border:1.5px solid var(--border);
  transition:border-color .3s ease, box-shadow .3s ease;
}
#stage .qs-api.bad{
  border-color:rgba(244,74,106,.65); box-shadow:0 0 0 1px rgba(244,74,106,.24), 0 0 50px rgba(244,74,106,.18);
  animation:qs-alert 1s ease-in-out infinite;
}
#stage .qs-api-h{ display:flex; align-items:center; gap:14px; }
#stage .qs-api-ic{
  width:48px; height:48px; border-radius:14px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.12); color:var(--accent-1);
}
#stage .qs-api-ic svg{ width:27px; height:27px; }
#stage .qs-api.bad .qs-api-ic{ background:rgba(244,74,106,.16); color:var(--danger); }
#stage .qs-api-n{ color:#fff; font-size:27px; font-weight:800; letter-spacing:-.4px; }
#stage .qs-api-b{
  margin-left:auto; padding:8px 16px; border-radius:100px; white-space:nowrap;
  border:1.5px solid rgba(240,166,74,.5); background:rgba(240,166,74,.12); color:var(--warn);
  font-family:var(--font-mono); font-size:18px; font-weight:700;
  transition:border-color .3s ease, background .3s ease, color .3s ease;
}
#stage .qs-api-b.bad{ border-color:rgba(244,74,106,.6); background:rgba(244,74,106,.16); color:var(--danger); }
#stage .qs-meter{ height:18px; border-radius:9px; background:rgba(35,44,64,.9); overflow:hidden; }
#stage .qs-meter i{
  display:block; height:100%; width:84%; border-radius:9px;
  background:linear-gradient(90deg,#F0A64A,#F4C46A);
  transition:width .5s cubic-bezier(.22,1,.36,1), background .3s ease;
}
#stage .qs-meter i.bad{ background:linear-gradient(90deg,#F44A6A,#FF8FA3); }
#stage .qs-meter i.ok{ background:linear-gradient(90deg,#3fb950,#7ee08a); }

#stage .qs-load{
  height:104px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:22px;
  background:rgba(20,27,43,.5); border:1.5px dashed var(--border);
  opacity:.32; filter:saturate(.25);
  transition:opacity .3s ease, filter .3s ease, border-color .3s ease, background .3s ease, box-shadow .3s ease;
}
#stage .qs-load.on{
  opacity:1; filter:none; border-style:solid; border-color:rgba(244,74,106,.6);
  background:rgba(244,74,106,.07);
  box-shadow:0 0 0 1px rgba(244,74,106,.2), 0 0 50px rgba(244,74,106,.14);
}
#stage .qs-load-n{ color:#fff; font-size:25px; font-weight:800; letter-spacing:-.3px; white-space:nowrap; }
#stage .qs-load-s{ color:var(--text-dim); font-family:var(--font-mono); font-size:18px; font-weight:600; white-space:nowrap; }
#stage .qs-load-b{
  margin-left:auto; padding:8px 18px; border-radius:100px; white-space:nowrap;
  border:1.5px solid rgba(244,74,106,.55); background:rgba(244,74,106,.16); color:var(--danger);
  font-family:var(--font-mono); font-size:20px; font-weight:800; letter-spacing:1.4px;
}

/* ====================== SCENE 2 · BLOB + QUEUE ========================= */
#stage .qs-store{ height:170px; flex-shrink:0; display:flex; align-items:stretch; gap:12px; }
#stage .qs-blob, #stage .qs-queue{
  flex:1; min-width:0; display:flex; flex-direction:column; gap:10px; justify-content:center;
  padding:16px 20px; border-radius:24px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2));
  border:1.5px solid var(--border);
  transition:border-color .3s ease, box-shadow .3s ease;
}
#stage .qs-queue{
  border-color:rgba(34,211,238,.5);
  box-shadow:0 0 0 1px rgba(34,211,238,.18), 0 0 50px rgba(34,211,238,.12);
}
#stage .qs-box-h{ display:flex; align-items:center; gap:12px; }
#stage .qs-box-ic{ font-size:26px; flex-shrink:0; }
#stage .qs-box-h b{ color:#fff; font-size:24px; font-weight:800; letter-spacing:-.3px; white-space:nowrap; }
#stage .qs-box-s{
  color:var(--text-primary); font-family:var(--font-mono); font-size:18px; font-weight:600;
  white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
}
#stage .qs-box-n{
  align-self:flex-start; padding:7px 15px; border-radius:10px; white-space:nowrap;
  background:rgba(139,149,167,.12); border:1.5px solid rgba(139,149,167,.3); color:var(--text-dim);
  font-family:var(--font-mono); font-size:19px; font-weight:700;
}
#stage .qs-box-n.hot{ background:rgba(34,211,238,.16); border-color:rgba(34,211,238,.55); color:var(--accent-cyan); }
#stage .qs-link{
  width:56px; flex-shrink:0; display:flex; flex-direction:column;
  align-items:center; justify-content:center; gap:8px;
}
#stage .qs-link i{
  display:block; width:24px; height:4px; border-radius:2px;
  background:var(--accent-cyan); box-shadow:0 0 12px rgba(34,211,238,.5);
  animation:qs-send 1.1s linear infinite;
}
#stage .qs-link i:nth-child(2){ animation-delay:.22s; }
#stage .qs-link i:nth-child(3){ animation-delay:.44s; }

#stage .qs-msg{
  height:140px; flex-shrink:0; display:flex; flex-direction:column; gap:11px; justify-content:center;
  padding:15px 20px; border-radius:22px;
  background:rgba(14,20,32,.7); border:1.5px solid var(--border);
  transition:border-color .3s ease, box-shadow .3s ease;
}
#stage .qs-msg.hot{
  border-color:rgba(34,211,238,.55);
  box-shadow:0 0 0 1px rgba(34,211,238,.2), 0 0 50px rgba(34,211,238,.14);
}
#stage .qs-msg-h{ display:flex; align-items:center; gap:14px; }
#stage .qs-msg-n{ color:#fff; font-size:23px; font-weight:800; letter-spacing:-.3px; white-space:nowrap; }
#stage .qs-msg-b{
  margin-left:auto; padding:6px 14px; border-radius:100px; white-space:nowrap;
  border:1.5px solid rgba(34,211,238,.5); background:rgba(34,211,238,.12); color:var(--accent-cyan);
  font-family:var(--font-mono); font-size:17px; font-weight:700;
}
#stage .qs-json{ display:flex; flex-direction:column; gap:3px; }
#stage .qs-json-l{
  color:var(--code-str); font-family:var(--font-mono); font-size:18px; font-weight:600;
  white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
}

#stage .qs-worker{
  flex:1; min-height:0; display:flex; flex-direction:column; gap:13px; justify-content:center;
  padding:18px 22px; border-radius:24px;
  background:linear-gradient(180deg, var(--bg-panel), var(--bg-panel-2));
  border:1.5px solid var(--border);
  transition:border-color .3s ease, box-shadow .3s ease;
}
#stage .qs-worker.busy{ border-color:rgba(58,160,255,.55); box-shadow:0 0 0 1px rgba(58,160,255,.22), 0 0 44px rgba(58,160,255,.14); }
#stage .qs-worker.ok{ border-color:rgba(63,185,80,.55); box-shadow:0 0 0 1px rgba(63,185,80,.22), 0 0 44px rgba(63,185,80,.14); }
#stage .qs-worker.bad{
  border-color:rgba(244,74,106,.65); box-shadow:0 0 0 1px rgba(244,74,106,.24), 0 0 50px rgba(244,74,106,.18);
  animation:qs-alert 1s ease-in-out infinite;
}
#stage .qs-wk-h{ display:flex; align-items:center; gap:13px; }
#stage .qs-wk-ic{
  width:48px; height:48px; border-radius:14px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.12); color:var(--accent-1);
}
#stage .qs-wk-ic svg{ width:27px; height:27px; }
#stage .qs-worker.busy .qs-wk-ic svg{ animation:msd-spin 2.6s linear infinite; }
#stage .qs-worker.ok .qs-wk-ic{ background:rgba(63,185,80,.16); color:var(--success); }
#stage .qs-worker.bad .qs-wk-ic{ background:rgba(244,74,106,.16); color:var(--danger); }
#stage .qs-wk-h b{ color:#fff; font-family:var(--font-mono); font-size:22px; font-weight:700; white-space:nowrap; }
#stage .qs-wk-s{
  color:var(--text-primary); font-family:var(--font-mono); font-size:20px; font-weight:600;
  white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
}
#stage .qs-worker.ok .qs-wk-s{ color:var(--success); }
#stage .qs-worker.bad .qs-wk-s{ color:var(--danger); }
#stage .qs-wk-row{ display:flex; gap:10px; }
#stage .qs-pill{
  flex:1; min-width:0; text-align:center; padding:10px 8px; border-radius:12px; white-space:nowrap;
  overflow:hidden; text-overflow:ellipsis;
  background:rgba(14,20,32,.75); border:1.5px solid var(--border); color:var(--text-dim);
  font-family:var(--font-mono); font-size:17px; font-weight:600;
  transition:border-color .3s ease, background .3s ease, color .3s ease;
}
#stage .qs-pill b{ color:#fff; font-weight:700; }
#stage .qs-pill.hot{ border-color:rgba(240,166,74,.6); background:rgba(240,166,74,.1); color:var(--warn); }
#stage .qs-pill.hot b{ color:var(--warn); }
#stage .qs-pill.ok{ border-color:rgba(63,185,80,.5); background:rgba(63,185,80,.1); color:var(--success); }
#stage .qs-pill.ok b{ color:var(--success); }
#stage .qs-pill.bad{ border-color:rgba(244,74,106,.6); background:rgba(244,74,106,.12); color:var(--danger); }
#stage .qs-pill.bad b{ color:var(--danger); }

#stage .qs-poison{
  height:92px; flex-shrink:0; display:flex; align-items:center; gap:14px;
  padding:0 20px; border-radius:20px;
  background:rgba(20,27,43,.5); border:1.5px dashed var(--border);
  opacity:.34; filter:saturate(.25);
  transition:opacity .3s ease, filter .3s ease, border-color .3s ease, background .3s ease;
}
#stage .qs-poison.on{
  opacity:1; filter:none; border-style:solid; border-color:rgba(244,74,106,.55);
  background:rgba(244,74,106,.07);
}
#stage .qs-poison-ic{
  width:44px; height:44px; border-radius:13px; flex-shrink:0; font-size:23px;
  display:flex; align-items:center; justify-content:center;
  background:rgba(244,74,106,.12); border:1.5px solid rgba(244,74,106,.3);
}
#stage .qs-poison-n{ color:#fff; font-family:var(--font-mono); font-size:21px; font-weight:700; white-space:nowrap; }
#stage .qs-poison-s{
  margin-left:auto; color:var(--text-dim); font-family:var(--font-mono);
  font-size:17px; font-weight:600; white-space:nowrap;
}

#stage .qs-strip{
  height:72px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:20px;
  background:rgba(20,27,43,.7); border:1.5px solid var(--border);
  transition:border-color .3s ease, background .3s ease;
}
#stage .qs-strip b{
  padding:6px 15px; border-radius:8px; flex-shrink:0;
  background:rgba(58,160,255,.16); color:var(--accent-1);
  font-family:var(--font-mono); font-size:18px; font-weight:800; letter-spacing:2px;
}
#stage .qs-strip span{ color:var(--text-primary); font-size:22px; font-weight:600; line-height:1.3; }
#stage .qs-strip.bad{ border-color:rgba(244,74,106,.5); background:rgba(244,74,106,.1); }
#stage .qs-strip.bad b{ background:rgba(244,74,106,.2); color:var(--danger); }
#stage .qs-strip.good{ border-color:rgba(63,185,80,.45); background:rgba(63,185,80,.09); }
#stage .qs-strip.good b{ background:rgba(63,185,80,.2); color:var(--success); }

/* ========================= SCENE 3 · WHICH QUEUE ======================= */
#stage .qs-split{ display:flex; gap:16px; height:100%; }
#stage .qs-col{
  flex:1; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:16px;
  padding:26px 18px; border-radius:28px; text-align:center;
}
#stage .qs-col.cheap{
  background:radial-gradient(circle at 50% 0%, rgba(34,211,238,.14), transparent 62%), rgba(20,27,43,.6);
  border:2px solid rgba(34,211,238,.55);
  box-shadow:0 0 0 1px rgba(34,211,238,.18), 0 0 60px rgba(34,211,238,.12);
}
#stage .qs-col.rich{ background:rgba(20,27,43,.6); border:2px solid rgba(58,160,255,.45); }
#stage .qs-col-h{ font-family:var(--font-mono); font-size:19px; font-weight:800; letter-spacing:1.6px; white-space:nowrap; }
#stage .qs-col.cheap .qs-col-h{ color:var(--accent-cyan); }
#stage .qs-col.rich .qs-col-h{ color:var(--accent-1); }
#stage .qs-col-ic{ font-size:56px; line-height:1; }
#stage .qs-col.cheap .qs-col-ic{ animation:msd-breathe 2.4s ease-in-out infinite; }
#stage .qs-col-list{ width:100%; display:flex; flex-direction:column; gap:10px; }
#stage .qs-row{
  padding:13px 10px; border-radius:13px;
  background:rgba(14,20,32,.7); border:1.5px solid var(--border); color:var(--text-dim);
  font-size:20px; font-weight:600; line-height:1.25;
}
#stage .qs-row b{ color:var(--text-primary); font-weight:800; }
#stage .qs-col.cheap .qs-row b{ color:#fff; }
#stage .qs-col-x{
  width:100%; padding:13px 10px; border-radius:14px;
  background:rgba(58,160,255,.12); border:1.5px solid rgba(58,160,255,.45); color:var(--accent-1);
  font-family:var(--font-mono); font-size:18px; font-weight:700; line-height:1.3;
}
#stage .qs-col-x.hot{ background:rgba(34,211,238,.16); border-color:rgba(34,211,238,.6); color:var(--accent-cyan); }

/* ========================== SCENE 4 · THE PAYOFF ======================= */
#stage .qs-final{
  height:100%; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:18px;
  text-align:center;
}
#stage .qs-badge{
  width:132px; height:132px; border-radius:36px; font-size:64px;
  display:flex; align-items:center; justify-content:center;
  background:linear-gradient(160deg, rgba(34,211,238,.28), rgba(58,160,255,.14));
  border:2px solid rgba(34,211,238,.6);
  box-shadow:0 0 0 1px rgba(34,211,238,.3), 0 0 80px rgba(34,211,238,.32);
  animation:msd-breathe 2.4s ease-in-out infinite;
}
